def count_nums(arr):
    count = 0
    for num in arr:
        if num == 0:
            continue  # The sum of digits of 0 is 0 which is not greater than 0
        digits = []
        # Handle negative numbers by preserving the sign of the first digit
        n = num
        is_negative = n < 0
        if is_negative:
            n = -n
        while n > 0:
            digits.append(n % 10)
            n = n // 10
        if digits:
            digits[-1] = -digits[-1] if is_negative else digits[-1]
        # Calculate the sum of signed digits
        if sum(digits) > 0:
            count += 1
    return count
